import axios from "axios";

const TMDB_API_KEY = "b56be59cfcfc26fbad50e51fb6341736"; // 🔑 실제 TMDB API 키를 입력하세요.
const BASE_URL = "https://api.themoviedb.org/3";
const IMAGE_BASE_URL = "https://image.tmdb.org/t/p/w780";

/**
 * KOFIC 국가 이름을 TMDB 국가 코드로 변환하는 헬퍼 함수
 */
const convertNationToCode = (nationName) => {
  const nationMap = {
    "한국": "KR", "미국": "US", "일본": "JP", "영국": "GB",
    "프랑스": "FR", "중국": "CN", "홍콩": "HK", "대만": "TW",
    "캐나다": "CA", "독일": "DE", "스페인": "ES",
  };
  return nationMap[nationName] || null;
};

/**
 * TMDB에서 정확한 영화 포스터를 가져오는 고도화된 함수 (v4 - 최종 디버깅)
 */
export const getPosterFromTMDB = async (title, year, options = {}) => {
  try {
    // 🚩 디버깅 로그 3: TMDB API 함수 시작 시점의 입력 값 확인
    console.log(`--- 3. getPosterFromTMDB 실행 ---`, { title, year, options });
    const searchPromises = [
      axios.get(`${BASE_URL}/search/movie`, { params: { api_key: TMDB_API_KEY, query: title, language: "ko-KR", include_adult: false } }),
    ];
    if (options.movieNmEn) {
      searchPromises.push(axios.get(`${BASE_URL}/search/movie`, { params: { api_key: TMDB_API_KEY, query: options.movieNmEn, language: "ko-KR", include_adult: false } }));
    }

    const responses = await Promise.all(searchPromises);
    const allResults = responses.flatMap(res => res.data.results);
    const uniqueResults = Array.from(new Map(allResults.map(movie => [movie.id, movie])).values());

    // 🚩 디버깅 로그 4: TMDB에서 찾은 모든 후보군 확인 (이 부분이 추가되었습니다!)
    console.log(`--- 4. TMDB 후보군 (${uniqueResults.length}개) ---`, uniqueResults);

    if (uniqueResults.length === 0) return null;

    const nationCode = options.nation ? convertNationToCode(options.nation) : null;

    // --- 매칭 로직 (우선순위 순) ---
    const getYear = (dateString) => dateString?.substring(0, 4);

    // 1순위: 국가와 연도가 정확히 일치
    if (nationCode && year) {
        const perfectMatch = uniqueResults.find(m => getYear(m.release_date) === year && m.origin_country?.includes(nationCode));
        if (perfectMatch) {
            console.log(`✅ [정확한 일치] "${title}" → 국가(${nationCode})+연도(${year})`);
            return `${IMAGE_BASE_URL}${perfectMatch.poster_path}`;
        }
    }

    // 2순위: 국가는 일치, 연도는 ±1년 오차 허용 (해외 영화 국내 개봉딜레이 고려)
    if (nationCode && year) {
        // parseInt를 사용하기 전에 유효한 값인지 확인하는 로직 추가
        const yearNum = parseInt(year);
        const flexibleYearMatch = uniqueResults.find(m => {
            const releaseYearStr = getYear(m.release_date);
            if (!releaseYearStr) return false;
            const releaseYearNum = parseInt(releaseYearStr);
            return (Math.abs(releaseYearNum - yearNum) <= 1) && m.origin_country?.includes(nationCode);
        });
        if (flexibleYearMatch) {
            console.log(`⚠️ [유연한 연도 일치] "${title}" → 국가(${nationCode})+연도(±1)`);
            return `${IMAGE_BASE_URL}${flexibleYearMatch.poster_path}`;
        }
    }
    
    // 3순위: 연도 무시, 국가만 일치하는 것 중 가장 인기도 높은 것
    if (nationCode) {
        const nationMatches = uniqueResults.filter(m => m.origin_country?.includes(nationCode));
        if (nationMatches.length > 0) {
            const mostPopularInNation = nationMatches.sort((a,b) => b.popularity - a.popularity)[0];
            console.log(`💡 [국가 우선 일치] "${title}" → 국가(${nationCode}) 일치 항목 중 인기도순`);
            return `${IMAGE_BASE_URL}${mostPopularInNation.poster_path}`;
        }
    }

    // 4순위: 위 모든 조건 불일치 시, 연도만이라도 맞춰보기 (국가 정보가 없는 경우 등)
    if (year) {
        const yearMatch = uniqueResults.find(m => getYear(m.release_date) === year);
        if(yearMatch) {
            console.log(`🤔 [연도 일치] "${title}" → 연도(${year}) 일치`);
            return `${IMAGE_BASE_URL}${yearMatch.poster_path}`;
        }
    }

    // 5순위: 최후의 수단, 전체 결과에서 가장 인기도 높은 것
    const bestGuess = uniqueResults.sort((a, b) => b.popularity - a.popularity)[0];
    console.log(`❓ [최선 추측] "${title}" → 전체 결과 중 인기도순`);
    return `${IMAGE_BASE_URL}${bestGuess.poster_path}`;

  } catch (error) {
    console.error(`TMDB API 오류 (${title}):`, error.message);
    return null;
  }
};
